import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/15-Man-vs-machine-man-loses-the-first-battle.html","title":"15-智能较量的开端：当人类遇上“思考”机器","lang":"zh-CN","frontmatter":{"title":"15-智能较量的开端：当人类遇上“思考”机器","icon":"read","date":"2025-04-16T07:33:17.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1767772409000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":22,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"866b91b8fbccfeac5b2862fbfab29b8f1fe59468","time":1767772409000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"886d8f15033f4c56bde764d46508e00dde3da2e0","time":1744847333000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Man-machine-war-the-computer-steal-the-trick"},{"hash":"34d1726ca148d0ca9f24eee4b09966e3108d3a8a","time":1744846423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"添加图片"},{"hash":"56e592286c820f07f372d0467e70517fa1793c61","time":1744846073000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"画一张：数学家马里恩·汀斯雷"},{"hash":"2b4d829c2c4bccc4c53078f052e11a53d8c61ff9","time":1744844694000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"change link"},{"hash":"ff5b6d449227cf19f609a0f703102931ba373050","time":1744810476000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"菜谱"},{"hash":"8433e7054a00672c3910459d51e62f8bfedb5d39","time":1744807621000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"38946e72375c7a4a85f21a7dc690aa5eaa59dd70","time":1744807391000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"3f6a20bfab8f8b2e981e8ac512b7330be3744ab1","time":1744805177000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"一半"},{"hash":"cd53467ddb937535aa4edf60382ca72fc1cbca8e","time":1744794770000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"ae0c39f7710801338bfc9e5cb985b0b935f22c48","time":1744760060000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.98,"words":2395},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/15-Man-vs-machine-man-loses-the-first-battle.md"}`),a={name:`15-Man-vs-machine-man-loses-the-first-battle.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>在日常生活中，我们时常会听到“人工智能”“AI”等词汇。这些高科技术语背后，隐藏着一场又一场令人着迷的较量：<strong>人类与计算机的对决</strong>。这种对决形式多种多样，往往以某种游戏为战场，双方在规则之内一较高下——不为娱乐，而是为了探寻智慧的边界。</p><p>如今再回顾这些比赛，我们发现一个明显的趋势：计算机接连战胜人类冠军。在游戏的世界里，难道我们真的已经全面落后于人工智能了吗？答案并非那么简单。这场“人机争锋”的故事，早在数十年前就已经悄然拉开序幕。</p><h2 id="_1-早期赛场的硝烟" tabindex="-1"><a class="header-anchor" href="#_1-早期赛场的硝烟"><span>1. 早期赛场的硝烟</span></a></h2><p>事实上，关于人机对抗的讨论并非近几年才开始，而是可以追溯到三十多年前。当时，这种较量不仅限于少数游戏，而是涵盖了扑克、象棋、围棋乃至各种电子游戏。不同于日常中轻松娱乐的游戏，这里的对弈通常由各领域的顶尖高手和专为此目的设计的计算机系统进行较量，战场因此显得格外引人注目。</p><p>特别值得一提的是棋类游戏。</p><figure><img src="/assets/image-20250417070411598-D_GLCBm2.png" alt="中国象棋" tabindex="0" loading="lazy"><figcaption>中国象棋</figcaption></figure><p>任何一局棋局，都充满了极其丰富的变化可能性。以中国象棋为例，其变化种类之多，甚至超过了 10 的 100 次方。正因如此，不论是人类还是机器，每一步决策都承载着巨大的挑战，成为智力和算法较量的绝佳试金石。</p><p>早期的一部分科学家曾设想：如果一台计算机能在国际象棋或围棋等棋类比赛中击败世界级高手，那么这台机器便可被认定拥有“真正的智能”。正是在这样的大背景下，棋类比赛逐渐成为人机对抗的重要舞台。</p><h2 id="_2-英国跳棋的启示" tabindex="-1"><a class="header-anchor" href="#_2-英国跳棋的启示"><span>2. 英国跳棋的启示</span></a></h2><figure><img src="/assets/raw-Dwddz8Hv.png" alt="英国跳棋" tabindex="0" loading="lazy"><figcaption>英国跳棋</figcaption></figure><p>在众多对弈项目中，英国跳棋无疑为这一领域提供了一段极富传奇色彩的历史。不同于我们平常所见的跳棋，英国跳棋的棋盘设计颇似国际象棋，其走法也带有独特规则——棋子不仅可以前进，还能跳跃对方棋子以完成“吃子”。</p><figure><img src="/assets/raw-20250417073106274-DQVXD6ug.png" alt="数学家·马里恩·汀斯雷｜英国跳棋王" tabindex="0" loading="lazy"><figcaption>数学家·马里恩·汀斯雷｜英国跳棋王</figcaption></figure><p>在这个领域中，有一位名震一时的棋手——数学家<strong>马里恩·汀斯雷</strong>。他不仅在英国跳棋界久占鳌头，整整四十年鲜有对手问鼎，还被尊称为“英国跳棋王”。然而，他的霸主地位最终被一款名为<strong>奇诺克</strong>的计算机程序所打破。</p><p>第一次交锋发生在1990年的一场表演赛上。当时，奇诺克的设计者信心满满，宣称这台机器能够预见未来二十步的可能局面。然而，经验丰富的汀斯雷以 4 比 2 取得了胜利，这场较量也让人们看到了人类智慧的魅力。</p><p>几年之后，1994年，两位对手再次站上赛场。这一次的比赛局势却截然不同：双方在六局内均未分出胜负，决胜局时，汀斯雷突然因突发的身体不适中断了比赛。经过后续检查，发现他已被诊断出晚期癌症，迫使他不得不退出竞赛。不久之后，这位传奇棋手离开了人世。由此，奇诺克不仅夺得了英国跳棋冠军的桂冠，还成为了世界上第一个在该领域立下汗马功劳的机器人。</p><h2 id="_3-计算机胜势背后的秘密" tabindex="-1"><a class="header-anchor" href="#_3-计算机胜势背后的秘密"><span>3. 计算机胜势背后的秘密</span></a></h2><p>为何计算机能在如此复杂的竞技中逐步占据上风？</p><p>核心原因在于其超凡的计算和预测能力。普通人类棋手可能只能大致预估接下来的八到十步，而先进的计算机程序如奇诺克则能够预测二十步之后的局面。</p><p>假如你在和同学下棋，当前这一步就你有5种走法，每种走法对手也有5种应对方法，如果你想考虑清楚每一步的后果，就要考虑25种不同的情况，25种，听着好像不太多对吧？别着急，这只是考虑当前这一步的呢。</p><p>我稍微带你计算一下：如果奇诺克真的能提前思考20步，它要思考多少种可能性呢？<strong>你可以拿一张纸，在上面写一个1，然后在后面写28个0，这就是奇诺克要考虑的可能性了</strong>。</p><p>在这巨量的可能分支中，计算机要找到最优解并不简单，但由于运算能力不断提升，计算机能更快、更稳定地完成这样的工作。这也让它在棋盘上的策略部署上，比人类选手更具有<strong>全局性</strong>和<strong>精确度</strong>。——这正是计算机能在密集信息中迅速锁定最佳策略的原因。</p><p>它靠的是什么呢？一种名为 <strong>“蒙特卡洛树搜索”</strong> 的策略。</p><h2 id="_4-把思考变成一棵树" tabindex="-1"><a class="header-anchor" href="#_4-把思考变成一棵树"><span>4. 把思考变成一棵树</span></a></h2><p>蒙特卡洛树搜索算法就像是一棵不断分叉的智慧之树，从根部一层层地展开每一种可能，直到找到最佳路径。这样的搜索方式，不仅被用在跳棋上，后来也成为国际象棋、围棋乃至 AlphaGo 等系统的核心算法。</p><p>（<strong>省字版｜便于理解</strong>：这种算法需要一层层一步步地进行，就像一棵大树，主干会分成细一些的枝干，每一条枝干又继续分成更多更细的枝干，一直分到最末端的树叶，所以人们就给这种方法起名叫蒙特卡洛树搜索。）</p><p>这种逐层分解、逐步推演的思维方式被称为<strong>结构化思考</strong>，对于日常生活同样很有用。比如，新学期伊始，你要组织一场班级才艺晚会，怎么 <strong>分工（分配任务）</strong> 最合理？简单粗放地一拍脑门就安排：得有人给演员们准备服装道具，得有人布置教室，好像还得找人去买点小零食水果。感觉怎么样？——听起来就没有条理，这样分配任务肯定容易疏漏。</p><p>而使用结构化思考，就可以这样：可以先把任务拆成“演员及节目准备（表演任务）”和“会场布置（班会会场布置）”两大块，在每块之下再细分——比如分成服装道具、主持人训练、教室布置、小零食采购、音响调试等等。像这样逐层细分，就更不容易出现遗漏或混乱。</p><figure><img src="/assets/raw-20250416203808059-u_kBt0Ne.png" alt="结构化思考" tabindex="0" loading="lazy"><figcaption>结构化思考</figcaption></figure><p><s><img src="/assets/raw-20250416205646642-Dgq52gnb.png" alt="结构化思考" loading="lazy"></s></p><figure><img src="/assets/Gemini_Generated_Image_ym5omvym5omvym5o-KLt8XZ2i.png" alt="结构化思考" tabindex="0" loading="lazy"><figcaption>结构化思考</figcaption></figure><p><strong>省字版</strong>：</p><ol><li><strong>先把任务分分类</strong>：表演任务、班会会场布置；</li><li><strong>细分成小任务</strong>： <ol><li><strong>表演任务</strong>： <ol><li>节目准备； <ol><li>可以继续细分……</li><li>可以继续细分……</li></ol></li><li>服装道具准备； <ol><li>可以继续细分……</li><li>可以继续细分……</li></ol></li><li>还有主持人排练等等。</li></ol></li><li><strong>班会会场布置</strong>： <ol><li>布置教室桌椅； <ol><li>可以继续细分……</li><li>可以继续细分……</li></ol></li><li>购买小零食； <ol><li>可以继续细分……</li><li>可以继续细分……</li></ol></li><li>调试音箱话筒等等。</li></ol></li></ol></li></ol><p>再大白话一些：其实就是类似平时用的思维导图，有兴趣的读者可以试一试用一用。</p><p>这样一类类、一层层地拆分任务，就比东想一个、西想一个要更有条理，更不容易遗漏。</p><h2 id="_4-迈向全球棋战的新时代" tabindex="-1"><a class="header-anchor" href="#_4-迈向全球棋战的新时代"><span>4. 迈向全球棋战的新时代</span></a></h2><figure><img src="/assets/%E5%9B%BD%E9%99%85%E8%B1%A1%E6%A3%8B-CuQ64qLO.png" alt="国际象棋" tabindex="0" loading="lazy"><figcaption>国际象棋</figcaption></figure><p><strong>棋盘换了，但战火未熄！</strong></p><p>从英国跳棋这一战来看，也许会有人说，玩英国跳棋的人不算多，真正的高手数量也有限。</p><p>所以，随着人机对弈的经验不断丰富，科技工作者开始将目光转向更具普及性的竞技项目——国际象棋。相比英国跳棋，国际象棋吸引了更多爱好者，高手云集的赛场竞争更加激烈。而国际象棋不仅在棋子的数量和种类上更为复杂，其规则的多样性也对计算机的处理能力提出了更高的要求。正因如此，国际象棋成为了新一代人机对决的热门选项，而未来的较量将为我们揭示更多智慧的碰撞与科技的进步。</p><p>在这一系列人机大战的故事背后，我们既能看到人工智能不断突破的进步，也能感受到人类智慧不懈追求完美的精神。更多激动人心的对决与发现，还将陆续在后续章节中展现，敬请期待。</p>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};